<?php
require_once __DIR__ . '/bad_helpers.php';
require_module_access('bad');
$search = trim($_GET['search'] ?? '');
$safe = mysqli_real_escape_string($mysqli, $search);
$where = $safe ? "WHERE b.document_no LIKE '%{$safe}%' OR b.po_number LIKE '%{$safe}%' OR b.customer_name LIKE '%{$safe}%'" : '';
$query = "SELECT b.*, SUM(p.photo_type='before') before_count, SUM(p.photo_type='after') after_count FROM bad_documents b LEFT JOIN bad_photos p ON p.bad_id=b.id {$where} GROUP BY b.id ORDER BY b.date_doc DESC,b.id DESC";
$result = mysqli_query($mysqli,$query); $success=flash_get('success'); $error=flash_get('error');
include __DIR__ . '/header.php';
?><div class="container-fluid"><div class="card shadow-sm"><div class="card-header d-flex justify-content-between align-items-center"><h5 class="mb-0"><i class="fas fa-images text-primary mr-2"></i>BAD (Before After Documentation)</h5><a href="bad_create.php" class="btn btn-primary"><i class="fas fa-plus mr-1"></i>Create BAD</a></div><div class="card-body">
<?php if($success): ?><div class="alert alert-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error) ?></div><?php endif; ?><form class="form-inline mb-3"><input name="search" class="form-control mr-2" value="<?= htmlspecialchars($search) ?>" placeholder="Cari nomor, PO, customer"><button class="btn btn-outline-primary"><i class="fas fa-search mr-1"></i>Cari</button></form>
<div class="table-responsive"><table class="table table-bordered table-striped"><thead class="thead-light"><tr><th>No Document</th><th>Date</th><th>PO</th><th>Customer</th><th>Before</th><th>After</th><th class="text-center">Action</th></tr></thead><tbody><?php if($result && mysqli_num_rows($result)): while($row=mysqli_fetch_assoc($result)): ?><tr><td><?= htmlspecialchars($row['document_no']) ?></td><td><?= date('d/m/Y',strtotime($row['date_doc'])) ?></td><td><?= htmlspecialchars($row['po_number'] ?: '-') ?></td><td><?= htmlspecialchars($row['customer_name']) ?></td><td><?= (int)$row['before_count'] ?></td><td><?= (int)$row['after_count'] ?></td><td class="text-center"><a class="btn btn-info btn-sm" title="Edit" href="bad_edit.php?id=<?= (int)$row['id'] ?>"><i class="fas fa-edit"></i></a> <a class="btn btn-warning btn-sm" title="Print" target="_blank" href="bad_print.php?id=<?= (int)$row['id'] ?>"><i class="fas fa-print"></i></a> <a class="btn btn-danger btn-sm" title="Hapus" onclick="return confirm('Hapus BAD ini?')" href="bad_delete.php?id=<?= (int)$row['id'] ?>"><i class="fas fa-trash"></i></a></td></tr><?php endwhile; else: ?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada data BAD. Gunakan tombol Create BAD untuk menambahkan dokumentasi.</td></tr><?php endif; ?></tbody></table></div></div></div></div><?php include __DIR__ . '/footer.php'; ?>